/**
 * Generate shared barrels, docs nav slices, examples catalog, and roadmap table
 * from packages/vue/registry/*.registry.json, plus the ESLint plugin's
 * component index from packages/{vue,themes}/manifests.
 */
import { createHash } from 'node:crypto'
import { mkdir, readdir, readFile, writeFile } from 'node:fs/promises'
import { join } from 'node:path'

import { format, resolveConfig } from 'prettier'
import ts from 'typescript'

const GENERATED_BANNER =
  '/** @generated by pnpm registries:write — do not edit. */\n'

/** @typedef {{
 *   schemaVersion: string
 *   slug: string
 *   familyOrder?: string[]
 *   vueBarrel?: string[]
 *   themesBarrel?: string[]
 *   themesCssImports?: string[]
 *   roadmapTablesMarkdown?: string
 * }} PrimitivesRegistry
 */

const DOC_CATEGORY_ORDER = [
  'actions',
  'forms',
  'navigation-disclosure',
  'overlays',
  'feedback',
  'utilities',
]

const DOC_CATEGORY_LABELS = {
  actions: 'Actions',
  forms: 'Forms',
  'navigation-disclosure': 'Navigation & disclosure',
  overlays: 'Overlays',
  feedback: 'Feedback',
  utilities: 'Utilities',
}

/** @typedef {{
 *   schemaVersion: string
 *   slug: string
 *   docs?: {
 *     title: string
 *     specStatus?: string
 *     link?: string
 *     specLink?: string
 *     category?: string
 *     sidebarLabel?: string
 *   }
 *   vueBarrel?: string[]
 *   themesBarrel?: string[]
 *   themesCss?: string
 *   examples?: { id: string; title: string; description: string; layer: string }[]
 *   roadmap?: Record<string, unknown>
 * }} FamilyRegistry
 */

export const REGISTRY_GITIGNORE_PATHS = [
  'packages/vue/src/.registries/',
  'packages/themes/src/.registries/',
  'packages/nuxt/src/.registries/',
  'packages/eslint-plugin/src/.registries/',
  'examples/.registries/',
  'apps/docs/.vitepress/.registries/',
  'docs/.registries/',
]

/**
 * @param {string} repositoryRoot
 */
export async function listFamilyRegistryFiles(repositoryRoot) {
  const registryDir = join(repositoryRoot, 'packages/vue/registry')
  const files = (await readdir(registryDir)).filter(
    (name) =>
      name.endsWith('.registry.json') && name !== 'primitives.registry.json',
  )
  files.sort((left, right) => left.localeCompare(right))
  return files.map((name) => join(registryDir, name))
}

/**
 * @param {string} repositoryRoot
 */
async function readPrimitives(repositoryRoot) {
  const path = join(
    repositoryRoot,
    'packages/vue/registry/primitives.registry.json',
  )
  const text = await readFile(path, 'utf8')
  return /** @type {PrimitivesRegistry} */ (JSON.parse(text))
}

/**
 * @param {string} path
 */
async function readFamily(path) {
  const text = await readFile(path, 'utf8')
  return /** @type {FamilyRegistry} */ (JSON.parse(text))
}

/**
 * @param {PrimitivesRegistry} primitives
 * @param {FamilyRegistry[]} families
 * @param {'vue' | 'themes'} kind
 */
function buildPackageBarrelBody(primitives, families, kind) {
  const barrelKey = kind === 'vue' ? 'vueBarrel' : 'themesBarrel'
  const defaultHeader =
    kind === 'vue'
      ? '/**\n * Public Vue package entry point. Named ESM exports are the primary API.\n */'
      : "/** Themed wrappers and default CSS. One `GhostBadge` or `GhostButton` import loads the stylesheet. */\nimport './default.css'\n"

  const lines = [defaultHeader]
  const bySlug = new Map(families.map((family) => [family.slug, family]))
  const seenSlugs = new Set()
  if (primitives[barrelKey]?.length) lines.push(...primitives[barrelKey])
  for (const slug of primitives.familyOrder ?? []) {
    seenSlugs.add(slug)
    const family = bySlug.get(slug)
    if (family?.[barrelKey]?.length) lines.push(...family[barrelKey])
  }
  for (const family of families) {
    if (seenSlugs.has(family.slug)) continue
    if (family[barrelKey]?.length) lines.push(...family[barrelKey])
  }
  return `${lines.join('\n')}\n`
}

/**
 * @param {PrimitivesRegistry} primitives
 * @param {FamilyRegistry[]} families
 */
function buildVuePublicApi(primitives, families) {
  return relocateBarrelImports(
    buildPackageBarrelBody(primitives, families, 'vue'),
  )
}

/**
 * Published declaration emit matches the pre-shim index.ts export surface.
 *
 * @param {PrimitivesRegistry} primitives
 * @param {FamilyRegistry[]} families
 */
function buildVuePublishIndex(primitives, families) {
  return buildPackageBarrelBody(primitives, families, 'vue')
}

/**
 * @param {PrimitivesRegistry} primitives
 * @param {FamilyRegistry[]} families
 */
function buildThemesPublicApi(primitives, families) {
  return relocateBarrelImports(
    buildPackageBarrelBody(primitives, families, 'themes'),
  )
}

/**
 * @param {PrimitivesRegistry} primitives
 * @param {FamilyRegistry[]} families
 */
function buildThemesPublishIndex(primitives, families) {
  return buildPackageBarrelBody(primitives, families, 'themes')
}

/**
 * Value (non-type) exports declared by barrel statements, in declaration order.
 * Parsed with the TypeScript scanner rather than a regex so multi-line
 * specifier lists, inline `type` modifiers, and `default as` aliases all
 * resolve the same way the compiler sees them.
 *
 * @param {string} source
 * @returns {{ name: string, imported: string, from: string }[]}
 */
export function barrelValueExports(source) {
  const file = ts.createSourceFile(
    'barrel.ts',
    source,
    ts.ScriptTarget.Latest,
    false,
    ts.ScriptKind.TS,
  )
  /** @type {{ name: string, imported: string, from: string }[]} */
  const exports = []
  for (const statement of file.statements) {
    if (
      !ts.isExportDeclaration(statement) ||
      statement.isTypeOnly ||
      !statement.exportClause ||
      !ts.isNamedExports(statement.exportClause) ||
      !statement.moduleSpecifier ||
      !ts.isStringLiteral(statement.moduleSpecifier)
    ) {
      continue
    }
    for (const element of statement.exportClause.elements) {
      if (element.isTypeOnly) continue
      exports.push({
        name: element.name.text,
        imported: (element.propertyName ?? element.name).text,
        from: statement.moduleSpecifier.text,
      })
    }
  }
  return exports
}

/** @param {Iterable<string>} names */
function sortedUnique(names) {
  return [...new Set(names)].sort((left, right) => left.localeCompare(right))
}

/**
 * Auto-import name lists derived from the package barrels, so the resolver and
 * the Nuxt module never keep a hand-maintained component list.
 *
 * - Headless components are the default exports of `.vue` SFCs re-exported by
 *   `@ghostvue/vue`. Keying on the SFC (not just the `Ghost` prefix) keeps a
 *   future non-component `Ghost*` value, such as an app plugin, out of the list.
 * - Headless composables are the `useGhost*` namespace documented as public.
 *   Lower-level helpers (`useFocusScope`, `useFloating`, ...) stay named-import
 *   only so a global auto-import cannot shadow same-named app composables.
 * - Themed components are the `Ghost*` values `@ghostvue/themes` exports.
 *
 * @param {PrimitivesRegistry} primitives
 * @param {FamilyRegistry[]} families
 */
export function buildAutoImportNames(primitives, families) {
  const vueExports = barrelValueExports(
    buildPackageBarrelBody(primitives, families, 'vue'),
  )
  const themesExports = barrelValueExports(
    buildPackageBarrelBody(primitives, families, 'themes'),
  )
  return {
    headlessComponents: sortedUnique(
      vueExports
        .filter(
          ({ name, imported, from }) =>
            imported === 'default' &&
            from.endsWith('.vue') &&
            /^Ghost[A-Z]/.test(name),
        )
        .map(({ name }) => name),
    ),
    headlessComposables: sortedUnique(
      vueExports
        .filter(({ name }) => /^useGhost[A-Z]/.test(name))
        .map(({ name }) => name),
    ),
    themedComponents: sortedUnique(
      themesExports
        .filter(({ name }) => /^Ghost[A-Z]/.test(name))
        .map(({ name }) => name),
    ),
  }
}

/**
 * @param {string} name
 * @param {string} doc
 * @param {string[]} values
 */
function formatNameList(name, doc, values) {
  const items = values.map((value) => `  '${value}',`).join('\n')
  return `/** ${doc} */\nexport const ${name}: readonly string[] = [\n${items}\n]\n`
}

/**
 * @param {ReturnType<typeof buildAutoImportNames>} names
 */
function buildVueResolverNames(names) {
  return (
    GENERATED_BANNER +
    formatNameList(
      'ghostVueComponentNames',
      'Headless `Ghost*` components exported by `@ghostvue/vue`.',
      names.headlessComponents,
    )
  )
}

/**
 * @param {ReturnType<typeof buildAutoImportNames>} names
 */
function buildNuxtAutoImportNames(names) {
  return [
    GENERATED_BANNER.trimEnd(),
    formatNameList(
      'headlessComponentNames',
      'Headless `Ghost*` components exported by `@ghostvue/vue`.',
      names.headlessComponents,
    ),
    formatNameList(
      'headlessComposableNames',
      'Public `useGhost*` composables exported by `@ghostvue/vue`.',
      names.headlessComposables,
    ),
    formatNameList(
      'themedComponentNames',
      'Themed `Ghost*` wrappers exported by `@ghostvue/themes`.',
      names.themedComponents,
    ),
  ].join('\n')
}

/**
 * @param {PrimitivesRegistry} primitives
 * @param {FamilyRegistry[]} families
 */
function buildThemesCssImports(primitives, families) {
  const bySlug = new Map(families.map((family) => [family.slug, family]))
  const imports = []
  if (primitives.themesCssImports?.length) {
    for (const file of primitives.themesCssImports) {
      imports.push(`@import './${file}';`)
    }
  } else {
    for (const slug of primitives.familyOrder ?? []) {
      const family = bySlug.get(slug)
      const css = family?.themesCss ?? `ghost-${slug}.css`
      if (family?.themesBarrel?.length) {
        imports.push(`@import './${css}';`)
      }
    }
  }
  return imports
    .map((line) => line.replace("@import './", "@import '../"))
    .join('\n')
    .concat('\n')
}

/**
 * @param {PrimitivesRegistry} primitives
 * @param {FamilyRegistry[]} families
 */
function buildExamplesArray(primitives, families) {
  const bySlug = new Map(families.map((family) => [family.slug, family]))
  const known = new Set()
  /** @type {FamilyRegistry['examples']} */
  const examples = []
  for (const entry of primitives.examplesOrdered ?? []) {
    if (known.has(entry.id)) continue
    known.add(entry.id)
    examples.push(entry)
  }
  for (const slug of primitives.familyOrder ?? []) {
    for (const entry of bySlug.get(slug)?.examples ?? []) {
      if (known.has(entry.id)) continue
      known.add(entry.id)
      examples.push(entry)
    }
  }
  return examples
}

/**
 * @param {FamilyRegistry['examples']} examples
 */
function formatExamplesCatalog(examples) {
  const entries = examples.map((example) => {
    const lines = [
      '  {',
      `    id: '${example.id}',`,
      `    title: '${example.title.replaceAll("'", "\\'")}',`,
      `    description: '${example.description.replaceAll("'", "\\'")}',`,
      `    layer: '${example.layer}',`,
      '  },',
    ]
    return lines.join('\n')
  })
  return `${GENERATED_BANNER}
export const ghostExamples = [
${entries.join('\n')}
] as const
`
}

/**
 * @param {string} value
 */
function escapeTsString(value) {
  return value.replaceAll("'", "\\'")
}

/**
 * @param {FamilyRegistry[]} families
 */
function documentedComponentFamilies(families) {
  return families.filter((family) => family.docs?.link)
}

/**
 * @param {FamilyRegistry[]} families
 */
function componentFamiliesByCategory(families) {
  const documented = documentedComponentFamilies(families)
  /** @type {Map<string, FamilyRegistry[]>} */
  const byCategory = new Map()
  for (const family of documented) {
    const category = family.docs?.category
    if (!category) {
      throw new Error(
        `packages/vue/registry/${family.slug}.registry.json is missing docs.category`,
      )
    }
    const bucket = byCategory.get(category) ?? []
    bucket.push(family)
    byCategory.set(category, bucket)
  }
  for (const members of byCategory.values()) {
    members.sort((left, right) =>
      (left.docs?.sidebarLabel ?? left.slug).localeCompare(
        right.docs?.sidebarLabel ?? right.slug,
      ),
    )
  }
  return byCategory
}

/**
 * @param {FamilyRegistry[]} families
 */
function buildDocsNavComponents(families) {
  const byCategory = componentFamiliesByCategory(families)
  const lines = [
    "      { text: 'Overview', link: '/components/' },",
    ...DOC_CATEGORY_ORDER.flatMap((categoryKey) => {
      const members = byCategory.get(categoryKey) ?? []
      if (members.length === 0) return []
      return [
        '      {',
        `        text: '${escapeTsString(DOC_CATEGORY_LABELS[categoryKey])}',`,
        '        items: [',
        ...members.map(
          (family) =>
            `          { text: '${escapeTsString(family.docs.sidebarLabel)}', link: '${family.docs.link}' },`,
        ),
        '        ],',
        '      },',
      ]
    }),
  ]
  const flatLinks = documentedComponentFamilies(families)
    .sort((left, right) => left.docs.link.localeCompare(right.docs.link))
    .map((family) => `  '${family.docs.link}',`)
  return `${GENERATED_BANNER}
import type { LlmsSidebarGroup } from '../generate-llms-txt'

export const generatedComponentSidebar: LlmsSidebarGroup['items'] = [
${lines.join('\n')}
]

export const generatedComponentPageLinks = [
${flatLinks.join('\n')}
] as const
`
}

/**
 * @param {string} repositoryRoot
 * @param {FamilyRegistry[]} families
 */
async function buildDocsNavCatalog(repositoryRoot, families) {
  const byCategory = componentFamiliesByCategory(families)
  const categoryBlocks = []
  for (const categoryKey of DOC_CATEGORY_ORDER) {
    const members = byCategory.get(categoryKey) ?? []
    if (members.length === 0) continue
    const itemLines = []
    for (const family of members) {
      const manifestPath = join(
        repositoryRoot,
        `packages/vue/manifests/ghost-${family.slug}.manifest.json`,
      )
      let description = ''
      try {
        const manifest = JSON.parse(await readFile(manifestPath, 'utf8'))
        if (typeof manifest.description === 'string') {
          description = manifest.description
        }
      } catch {
        description = ''
      }
      itemLines.push(
        '        {',
        `          label: '${escapeTsString(family.docs.sidebarLabel)}',`,
        `          link: '${family.docs.link}',`,
        `          description: '${escapeTsString(description)}',`,
        '        },',
      )
    }
    categoryBlocks.push(
      '    {',
      `      category: '${escapeTsString(DOC_CATEGORY_LABELS[categoryKey])}',`,
      `      categoryKey: '${categoryKey}',`,
      '      items: [',
      ...itemLines,
      '      ],',
      '    },',
    )
  }
  return `${GENERATED_BANNER}
export interface GeneratedComponentCatalogEntry {
  label: string
  link: string
  description: string
}

export interface GeneratedComponentCatalogGroup {
  category: string
  categoryKey: string
  items: GeneratedComponentCatalogEntry[]
}

export const generatedComponentCatalog: GeneratedComponentCatalogGroup[] = [
${categoryBlocks.join('\n')}
]
`
}

/**
 * @param {FamilyRegistry[]} families
 */
function buildDocsNavSpecs(families) {
  const items = families
    .filter((family) => family.docs?.specLink)
    .sort((left, right) =>
      (left.docs?.sidebarLabel ?? left.slug).localeCompare(
        right.docs?.sidebarLabel ?? right.slug,
      ),
    )
    .map(
      (family) =>
        `      { text: '${escapeTsString(family.docs.sidebarLabel)}', link: '${family.docs.specLink}' },`,
    )
  return `${GENERATED_BANNER}
import type { LlmsSidebarGroup } from '../generate-llms-txt'

export const generatedContributingSpecItems: LlmsSidebarGroup['items'] = [
${items.join('\n')}
]
`
}

/** Component packages whose manifests feed `@ghostvue/eslint-plugin`. */
const ESLINT_INDEX_PACKAGES = [
  { name: '@ghostvue/vue', manifests: 'packages/vue/manifests' },
  { name: '@ghostvue/themes', manifests: 'packages/themes/manifests' },
]

/** @typedef {{
 *   name: string
 *   props?: { name: string }[]
 *   models?: { prop: string }[]
 *   slots?: { name: string }[]
 * }} ManifestContract
 */

/**
 * Manifests keyed by component name. A missing directory yields an empty map so
 * fixture workspaces without manifests still generate an (empty) index.
 *
 * @param {string} repositoryRoot
 * @param {string} directory
 */
async function readManifestContracts(repositoryRoot, directory) {
  /** @type {Map<string, ManifestContract & { stem: string }>} */
  const contracts = new Map()
  let files
  try {
    files = await readdir(join(repositoryRoot, directory))
  } catch {
    return contracts
  }
  for (const file of files.filter((name) => name.endsWith('.manifest.json'))) {
    const manifest = /** @type {ManifestContract} */ (
      JSON.parse(await readFile(join(repositoryRoot, directory, file), 'utf8'))
    )
    contracts.set(manifest.name, {
      ...manifest,
      stem: file.slice(0, -'.manifest.json'.length),
    })
  }
  return contracts
}

/**
 * Public docs page for a manifest: the longest documented family slug that
 * prefixes the manifest stem (`ghost-dialog-close` -> `dialog`), else the
 * component index.
 *
 * @param {string} stem
 * @param {string[]} documentedSlugs
 */
function docsSlugForManifest(stem, documentedSlugs) {
  const bare = stem.replace(/^ghost-/, '')
  let best = 'index'
  for (const slug of documentedSlugs) {
    const matches = bare === slug || bare.startsWith(`${slug}-`)
    if (matches && (best === 'index' || slug.length > best.length)) {
      best = slug
    }
  }
  return best
}

/**
 * Static usage contract for `@ghostvue/eslint-plugin`: prop, v-model, and slot
 * names per package and component, plus the docs page slug.
 *
 * Themed manifests are hand-written and list only what the wrapper adds, while
 * every themed wrapper sets `inheritAttrs: false` and forwards attrs and slots
 * to the unstyled component of the same name. The themed contract is therefore
 * the union of both manifests. The headless contract never borrows from themes,
 * which is how the rules tell `@ghostvue/vue` and `@ghostvue/themes` apart.
 *
 * @param {string} repositoryRoot
 * @param {FamilyRegistry[]} families
 */
async function buildEslintComponentIndex(repositoryRoot, families) {
  const documentedSlugs = families
    .map((family) => family.docs?.link)
    .filter((link) => typeof link === 'string')
    .map((link) => link.replace(/^\/components\//, ''))
  /** @type {Map<string, Map<string, ManifestContract & { stem: string }>>} */
  const byPackage = new Map()
  for (const pkg of ESLINT_INDEX_PACKAGES) {
    byPackage.set(
      pkg.name,
      await readManifestContracts(repositoryRoot, pkg.manifests),
    )
  }
  const headless = byPackage.get('@ghostvue/vue') ?? new Map()

  /** @type {Record<string, Record<string, unknown>>} */
  const index = {}
  for (const pkg of ESLINT_INDEX_PACKAGES) {
    const contracts = byPackage.get(pkg.name) ?? new Map()
    /** @type {Record<string, unknown>} */
    const components = {}
    for (const name of sortedUnique(contracts.keys())) {
      const own = contracts.get(name)
      if (!own) continue
      const sources =
        pkg.name === '@ghostvue/themes' && headless.has(name)
          ? [own, headless.get(name)]
          : [own]
      components[name] = {
        props: sortedUnique(
          sources.flatMap((source) =>
            (source?.props ?? []).map((prop) => prop.name),
          ),
        ),
        models: sortedUnique(
          sources.flatMap((source) =>
            (source?.models ?? []).map((model) => model.prop),
          ),
        ),
        slots: sortedUnique(
          sources.flatMap((source) =>
            (source?.slots ?? []).map((slot) => slot.name),
          ),
        ),
        docs: docsSlugForManifest(own.stem, documentedSlugs),
      }
    }
    index[pkg.name] = components
  }

  return `${GENERATED_BANNER}
/**
 * Component usage contracts generated from packages/vue/manifests and
 * packages/themes/manifests. Typed by ../component-index.ts.
 */
export const generatedComponentIndex = ${JSON.stringify(index, null, 2)} as const
`
}

/**
 * @param {string} body
 * @param {string} filepath
 */
async function formatTypescript(body, filepath) {
  const options = await resolveConfig(filepath)
  return format(body, { ...options, filepath })
}

/**
 * @param {string} repositoryRoot
 * @param {boolean} write
 */
export async function syncRepositoryRegistries({ repositoryRoot, write }) {
  const primitives = await readPrimitives(repositoryRoot)
  const familyPaths = await listFamilyRegistryFiles(repositoryRoot)
  const families = await Promise.all(
    familyPaths.map((path) => readFamily(path)),
  )

  const autoImportNames = buildAutoImportNames(primitives, families)

  const outputs = new Map([
    [
      'packages/vue/src/.registries/component-names.generated.ts',
      buildVueResolverNames(autoImportNames),
    ],
    [
      'packages/nuxt/src/.registries/auto-imports.generated.ts',
      buildNuxtAutoImportNames(autoImportNames),
    ],
    [
      'packages/vue/src/.registries/public-api.generated.ts',
      GENERATED_BANNER + buildVuePublicApi(primitives, families),
    ],
    [
      'packages/vue/src/.publish-index.generated.ts',
      buildVuePublishIndex(primitives, families),
    ],
    [
      'packages/themes/src/.registries/public-api.generated.ts',
      GENERATED_BANNER + buildThemesPublicApi(primitives, families),
    ],
    [
      'packages/themes/src/.publish-index.generated.ts',
      buildThemesPublishIndex(primitives, families),
    ],
    [
      'packages/themes/src/.registries/component-imports.generated.css',
      buildThemesCssImports(primitives, families),
    ],
    [
      'examples/.registries/examples-catalog.generated.ts',
      await formatTypescript(
        formatExamplesCatalog(buildExamplesArray(primitives, families)),
        join(repositoryRoot, 'examples/registry.ts'),
      ),
    ],
    [
      'apps/docs/.vitepress/.registries/docs-nav.components.generated.ts',
      await formatTypescript(
        buildDocsNavComponents(families),
        join(repositoryRoot, 'apps/docs/.vitepress/docs-nav.ts'),
      ),
    ],
    [
      'apps/docs/.vitepress/.registries/docs-nav.catalog.generated.ts',
      await formatTypescript(
        await buildDocsNavCatalog(repositoryRoot, families),
        join(repositoryRoot, 'apps/docs/.vitepress/docs-nav.ts'),
      ),
    ],
    [
      'apps/docs/.vitepress/.registries/docs-nav.specs.generated.ts',
      await formatTypescript(
        buildDocsNavSpecs(families),
        join(repositoryRoot, 'apps/docs/.vitepress/docs-nav.ts'),
      ),
    ],
    [
      'packages/eslint-plugin/src/.registries/component-index.generated.ts',
      await formatTypescript(
        await buildEslintComponentIndex(repositoryRoot, families),
        join(repositoryRoot, 'packages/eslint-plugin/src/index.ts'),
      ),
    ],
  ])

  if (primitives.roadmapTablesMarkdown) {
    outputs.set(
      'docs/.registries/roadmap-tables.generated.md',
      primitives.roadmapTablesMarkdown.trimEnd() + '\n',
    )
  }

  const violations = []

  if (primitives.roadmapTablesMarkdown) {
    const vueExports = barrelValueExports(
      buildPackageBarrelBody(primitives, families, 'vue'),
    )
    const themesExports = barrelValueExports(
      buildPackageBarrelBody(primitives, families, 'themes'),
    )
    const vueExportNames = new Set(vueExports.map(({ name }) => name))
    const themesExportNames = new Set(themesExports.map(({ name }) => name))

    violations.push(
      ...findRoadmapStatusDrift({
        tablesMarkdown: primitives.roadmapTablesMarkdown,
        vueExportNames,
      }),
    )
    violations.push(
      ...(await syncRoadmapTables({
        repositoryRoot,
        tablesMarkdown: primitives.roadmapTablesMarkdown,
        exportsMarkdown: buildRoadmapExportsMarkdown({
          vueExportNames,
          themesExportNames,
        }),
        write,
      })),
    )
  }

  if (write) {
    for (const [relativePath, content] of outputs) {
      const absolutePath = join(repositoryRoot, relativePath)
      await mkdir(join(absolutePath, '..'), { recursive: true })
      await writeFile(absolutePath, content)
    }
    return { violations, written: [...outputs.keys()], checked: [] }
  }

  for (const [relativePath, expected] of outputs) {
    const absolutePath = join(repositoryRoot, relativePath)
    let actual
    try {
      actual = await readFile(absolutePath, 'utf8')
    } catch {
      violations.push(`${relativePath} is missing. Run: pnpm registries:write`)
      continue
    }
    if (actual !== expected) {
      violations.push(
        `${relativePath} is stale versus registry metadata. Run: pnpm registries:write`,
      )
    }
  }

  return { violations, written: [], checked: [...outputs.keys()] }
}

/**
 * @param {string} content
 */
export function hashContent(content) {
  return createHash('sha256').update(content).digest('hex')
}

/** Generated barrels live under `src/.registries/`; barrel exports use `../`. */
export function relocateBarrelImports(source) {
  return source
    .replace(/^import '\.\/default\.css'\s*\n+/m, '')
    .replaceAll("from './", "from '../")
    .replaceAll("import './", "import '../")
}

const ROADMAP_BEGIN = '<!-- @generated registries:roadmap-tables begin -->'
const ROADMAP_END = '<!-- @generated registries:roadmap-tables end -->'
const ROADMAP_EXPORTS_BEGIN =
  '<!-- @generated registries:roadmap-exports begin -->'
const ROADMAP_EXPORTS_END = '<!-- @generated registries:roadmap-exports end -->'
const STALE_ROADMAP_STATUS_RE = /^(?:planned|in progress|in review)\b/i

/**
 * @param {string} left
 * @param {string} right
 */
function compareCaseInsensitive(left, right) {
  return left.localeCompare(right, 'en', { sensitivity: 'base' })
}

/**
 * @param {{ vueExportNames: Iterable<string>; themesExportNames: Iterable<string> }} options
 */
export function buildRoadmapExportsMarkdown({
  vueExportNames,
  themesExportNames,
}) {
  const vueNames = sortedUnique(vueExportNames)
    .sort(compareCaseInsensitive)
    .map((name) => `\`${name}\``)
    .join(', ')
  const themesNames = sortedUnique(themesExportNames)
    .sort(compareCaseInsensitive)
    .map((name) => `\`${name}\``)
    .join(', ')

  return [
    `\`master\` (\`packages/vue/src/index.ts\`, \`@ghostvue/vue\`) value exports: ${vueNames}. The same entry point also exports TypeScript-only types (props, \`*RootProps\`, exposed handles, contexts, and \`Use*\` options types) for every symbol above.`,
    '',
    `\`@ghostvue/themes\` (\`packages/themes/src/index.ts\`) value exports: ${themesNames}. It reuses the themed component names from \`@ghostvue/vue\` but does not export headless-only symbols (\`GhostPortal\`, \`GhostVisuallyHidden\`, shared composables such as \`useGhostId\` / \`useControllableState\` / \`useFocusScope\` / \`useRovingFocus\` / \`useDismissableLayer\` / \`useFloating\`, \`getPaginationRange\`, component \`useGhost*\` composables, or tooltip helpers \`ghostTooltipContextKey\` / \`mergeTooltipDescribedBy\` / \`resolveTooltipHtmlElement\`). Type-only themed prop aliases ship alongside those values.`,
  ].join('\n')
}

/**
 * Detects components exported from `@ghostvue/vue` that are still marked as
 * `planned`, `in progress`, or `in review` in the roadmap table.
 *
 * @param {{ tablesMarkdown: string; vueExportNames: Set<string> }} options
 * @returns {string[]}
 */
export function findRoadmapStatusDrift({ tablesMarkdown, vueExportNames }) {
  /** @type {string[]} */
  const violations = []
  for (const line of tablesMarkdown.split('\n')) {
    if (!/^\|\s*\d+\s*\|/.test(line)) continue
    const cols = line.split('|').map((cell) => cell.trim())
    const componentCell = cols[2] ?? ''
    const statusCell = cols[5] ?? ''
    if (!STALE_ROADMAP_STATUS_RE.test(statusCell)) continue

    const componentNames = [
      ...componentCell.matchAll(/`(Ghost[A-Za-z0-9]+)`/g),
    ].map((match) => match[1])
    const exportedMatches = componentNames.filter((name) =>
      vueExportNames.has(name),
    )
    if (exportedMatches.length === 0) continue

    violations.push(
      `docs/roadmap.md (primitives.registry.json roadmapTablesMarkdown): ${exportedMatches.join(' / ')} is exported from @ghostvue/vue but marked "${statusCell}" instead of "merged (<issue>)".`,
    )
  }
  return violations
}

/**
 * @param {string} source
 * @param {string} beginMarker
 * @param {string} endMarker
 * @param {string} replacement
 */
function replaceGeneratedRegion(source, beginMarker, endMarker, replacement) {
  const begin = source.indexOf(beginMarker)
  const end = source.indexOf(endMarker)
  if (begin === -1 || end === -1 || end <= begin) {
    return null
  }
  return (
    source.slice(0, begin + beginMarker.length) +
    '\n' +
    replacement.trimEnd() +
    '\n' +
    source.slice(end)
  )
}

/**
 * @param {{
 *   repositoryRoot: string
 *   tablesMarkdown: string
 *   exportsMarkdown?: string
 *   write: boolean
 * }} options
 */
export async function syncRoadmapTables({
  repositoryRoot,
  tablesMarkdown,
  exportsMarkdown,
  write,
}) {
  const roadmapPath = join(repositoryRoot, 'docs/roadmap.md')
  const source = await readFile(roadmapPath, 'utf8')

  let updated = replaceGeneratedRegion(
    source,
    ROADMAP_BEGIN,
    ROADMAP_END,
    tablesMarkdown,
  )
  if (updated === null) {
    return [
      'docs/roadmap.md is missing registry table markers. Add registries begin/end comments.',
    ]
  }

  if (exportsMarkdown !== undefined) {
    const withExports = replaceGeneratedRegion(
      updated,
      ROADMAP_EXPORTS_BEGIN,
      ROADMAP_EXPORTS_END,
      exportsMarkdown,
    )
    if (withExports === null) {
      return [
        'docs/roadmap.md is missing registry exports markers. Add roadmap-exports begin/end comments.',
      ]
    }
    updated = withExports
  }

  const options = await resolveConfig(roadmapPath)
  const formatted = await format(updated, {
    ...options,
    filepath: roadmapPath,
  })
  if (!write) {
    return source === formatted
      ? []
      : [
          'docs/roadmap.md generated regions are stale. Run: pnpm registries:write',
        ]
  }
  await writeFile(roadmapPath, formatted)
  return []
}
